static class Checks {
 static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
 static Plan Dense(double speed=1,int loops=1){var plan=new Plan{Speed=speed,Loops=loops};for(int i=0;i<160;i++)plan.Steps.Add(new(){Kind=ActionKind.Move,X=i,Y=i,Duration=0,Interval=2});return plan;}
 static Plan WaitPlan(int duration)=>new(){Steps=new(){new(){Kind=ActionKind.Wait,Duration=duration,Interval=0}}};
 static async Task Timing(double speed,int outputCost=0){var sink=new FakeMouse{Cost=outputCost};var engine=new Engine(sink,new FakeRecorder());var sw=Stopwatch.StartNew();await engine.Run(Dense(speed));double actual=sw.Elapsed.TotalMilliseconds,expected=320/speed;Console.WriteLine($"Dense 160x2ms, {speed}x, sink overhead {outputCost}ms: {actual:F1}ms (target {expected:F0})");Assert(actual<expected+140&&actual>expected*.75,"Timing drift");Assert(sink.Moves==160,"Dropped movement events");Assert(sink.Releases==1,"Did not release after normal completion");Assert(engine.State==EngineState.Idle,"Not idle after playback");}
 static async Task RuntimeSpeed(){var sink=new FakeMouse();var engine=new Engine(sink,new FakeRecorder());var sw=Stopwatch.StartNew();var task=engine.Run(WaitPlan(1000));await Task.Delay(200);engine.SetSpeed(2);await task;double ms=sw.Elapsed.TotalMilliseconds;Console.WriteLine($"Live 1x->2x: {ms:F1}ms (target ~600)");Assert(ms>490&&ms<790,"Runtime speed change not effective");}
 static async Task PauseAndResume(){var engine=new Engine(new FakeMouse(),new FakeRecorder());var sw=Stopwatch.StartNew();var task=engine.Run(WaitPlan(400));await Task.Delay(100);engine.Paused=true;await Task.Delay(230);Assert(!task.IsCompleted,"Continued during pause");engine.Paused=false;await task;var ms=sw.Elapsed.TotalMilliseconds;Console.WriteLine($"Pause/resume: {ms:F1}ms (target ~630)");Assert(ms>580&&ms<850,"Pause duration mishandled");engine.Paused=true;Assert(engine.State==EngineState.Idle,"Pause affected idle");}
 static async Task StopHeldButton(){var sink=new FakeMouse();var recorder=new FakeRecorder();var engine=new Engine(sink,recorder);var p=new Plan{Loops=0,LoopDelay=0,Steps=new(){new(){Kind=ActionKind.Down,Interval=0,Duration=0},new(){Kind=ActionKind.Wait,Duration=10000,Interval=0}}};var task=engine.Run(p);while(!sink.Held)await Task.Delay(1);engine.Paused=true;engine.Record();Assert(recorder.Starts==0,"Recording started during playback");var sw=Stopwatch.StartNew();engine.Stop();Assert(engine.State==EngineState.Stopping,"Stop allowed an early restart");await task;Assert(sw.ElapsedMilliseconds<150&&!sink.Held&&sink.Releases==1&&engine.State==EngineState.Idle,"Stop failed to cancel paused playback/release buttons");Console.WriteLine("Stop while paused/held button: PASS");}
 static async Task DisposeDuringPlayback(){var sink=new FakeMouse();var engine=new Engine(sink,new FakeRecorder());var task=engine.Run(new Plan{Steps=new(){new(){Kind=ActionKind.Down,Interval=0},new(){Kind=ActionKind.Wait,Duration=10000,Interval=0}}});while(!sink.Held)await Task.Delay(1);engine.Dispose();Assert(!sink.Held&&sink.Releases==1,"Window close returned before release");await task;Console.WriteLine("Dispose waits for worker release: PASS");}
