   var b=Button(w,name);b.GetBindingExpression(UIElement.IsEnabledProperty)?.UpdateTarget();b.GetBindingExpression(ContentControl.ContentProperty)?.UpdateTarget();Assert(b.IsEnabled==enabled&&Equals(b.Content,text),"Bound toolbar state incorrect: "+name+$" actual={b.IsEnabled}/{b.Content}, expected={enabled}/{text}");
  }
