  Assert(vm.CanRecord&&!vm.CanRun&&!vm.CanPause,"Empty plan initial state wrong");BoundState(w,vm);
  vm.Selected!.Steps.Add(new(){Kind=ActionKind.Wait,Duration=1000,Interval=0});Assert(vm.CanRun,"Run did not enable after adding a step");
  Button(w,"RecordButton").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Assert(vm.RecordText.Contains("停止录制")&&!vm.CanRun&&!vm.CanEdit&&!vm.CanChangeSpeed,"Recording interlocks incorrect");BoundState(w,vm);
  var other=new Plan();vm.Selected=other;Assert(vm.Selected!=other,"Plan switch permitted during recording");
  recorder.Emit(new(){Kind=ActionKind.Move,Duration=0,Interval=2});int count=vm.Selected!.Steps.Count;
  await engine.Run(vm.Selected);Assert(engine.Recording,"Replay started during capture");Button(w,"RecordButton").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Assert(vm.Selected.Steps.Count==1&&vm.Selected.Steps[0].Kind==ActionKind.Move,"Recording overwrite was not committed");
  var task=engine.Run(vm.Selected);Assert(!vm.CanRecord&&vm.CanRun&&vm.CanPause&&!vm.CanEdit&&vm.RunText.Contains("停止方案"),"Running interlocks incorrect");BoundState(w,vm);
  Button(w,"PauseButton").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Assert(engine.Paused&&vm.PauseText.Contains("恢复"),"Pause button did not toggle");BoundState(w,vm);
  vm.PlaybackSpeed=2;Assert(vm.Selected.Speed==2,"Speed not stored with plan");
  Button(w,"PauseButton").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Assert(!engine.Paused,"Resume button did not toggle");
  Button(w,"RunButton").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));await task;
  Assert(vm.CanEdit&&vm.CanRecord&&!vm.CanPause&&!sink.Held,"Idle controls not restored");BoundState(w,vm);
  Assert(recorder.Starts==1,"Capture conflict");Console.WriteLine("WPF bindings, toggle buttons, capture queue, editing locks: PASS");
 }
 static void LayoutCheck(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);if(child is Button b&&b.Name is "RecordButton" or "RunButton" or "PauseButton"){var h=b.ActualHeight;var width=b.ActualWidth;b.Measure(new Size(double.PositiveInfinity,double.PositiveInfinity));Assert(h+.5>=b.DesiredSize.Height-b.Margin.Top-b.Margin.Bottom&&width+.5>=b.DesiredSize.Width-b.Margin.Left-b.Margin.Right,"Toolbar clipping: "+b.Name);}LayoutCheck(child);}}
