  var original=steps.Select(s=>(s.Kind,s.Interval,s.Duration)).ToArray();vm.FilterIndex=0;Assert(vm.StepsView!.Cast<Step>().Count()==502,"All filter lost moves");vm.FilterIndex=2;Assert(vm.StepsView!.Cast<Step>().Single()==click,"Click filter incorrect");vm.Search="#501";Assert(vm.StepsView!.Cast<Step>().Single()==click,"Number search incorrect");vm.Search="880";Assert(vm.StepsView!.Cast<Step>().Single()==click,"Coordinate search incorrect");
  click.Kind=ActionKind.Wheel;Assert(vm.StepsView!.Cast<Step>().Count()==0,"Editing kind did not re-filter");click.Kind=ActionKind.LeftClick;vm.Search="";vm.FilterIndex=1;Assert(vm.NavigateImportant(1)==click&&vm.NavigateImportant(1)==wait&&vm.NavigateImportant(-1)==click,"Important navigation incorrect");Assert(steps.Select(s=>(s.Kind,s.Interval,s.Duration)).SequenceEqual(original),"Filtering changed recorded timeline");
