  typeof(MainWindow).GetMethod("Down",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.Invoke(window,new object[]{window,new RoutedEventArgs()});Assert(steps[501]==click&&click.Number==502,"Filtered reorder used display index");
  int beforeAdd=steps.Count;bool handled=false;typeof(MainWindow).GetMethod("Hook",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.Invoke(window,new object[]{IntPtr.Zero,0x312,new IntPtr(6),IntPtr.Zero,handled});Assert(steps.Count==beforeAdd+1&&vm.SelectedStep?.Kind==ActionKind.LeftClick,"Add-step hotkey dispatch failed");
  Console.WriteLine("500 hidden moves + original numbering/search/live filter/navigation/reorder/add hotkey: PASS");
 }
