  Console.WriteLine("3-second countdown contract, cancellation and preparation interlocks: PASS");
 }
 static void Shortcuts(){
  Assert(Shortcut.Parse("Ctrl+Alt+A")==Shortcut.Parse("alt+control+a"),"Modifier normalization failed");Assert(Shortcut.Parse("Win+Shift+F6").Modifiers==12,"Win/Shift missing");
  foreach(var invalid in new[]{"Ctrl","Ctrl+Ctrl+A","F6+F7","","Ctrl+None"})try{Shortcut.Parse(invalid);throw new Exception("Accepted bad shortcut: "+invalid);}catch(ArgumentException){}
