  var duplicate=settings.Copy();duplicate.Add="F6";try{manager.Apply(duplicate,Array.Empty<Plan>());throw new Exception("Duplicate accepted");}catch(ArgumentException){}Assert(registry.Registered.Count==6,"Validation unregistered old shortcuts");
  var conflict=settings.Copy();conflict.Record="F12";registry.Blocked=Shortcut.Parse("F12");try{manager.Apply(conflict,Array.Empty<Plan>());throw new Exception("Conflict accepted");}catch(InvalidOperationException){}Assert(registry.Registered.Count==6&&registry.Registered[1]==Shortcut.Parse("F6"),"Conflict did not restore shortcuts");
  manager.Suspend();Assert(registry.Registered.Count==0,"Settings editor did not suspend shortcuts");manager.Resume();Assert(registry.Registered.Count==6,"Cancel did not restore shortcuts");
  var plan=new Plan{Shortcut="Ctrl+Shift+F11"};manager.Apply(settings,new[]{plan});Assert(manager.FindPlan(100)==plan&&registry.Registered[100]==Shortcut.Parse(plan.Shortcut),"Per-plan combination missing");var vm=new MainViewModel(new Engine(new FakeMouse(),new FakeRecorder()),false);settings.Record="Ctrl+Shift+R";vm.ApplySettings(settings);Assert(vm.RecordText.Contains(settings.Record)&&vm.ToolbarHint.Contains(settings.Stop)&&vm.AddText.Contains(settings.Add),"Dynamic shortcut hints stale");
  Console.WriteLine("Shortcut parser, duplicate detection, registration rollback/suspend/resume/plan shortcuts: PASS");
 }
