  var include=new RecordedInputBuffer(0,true,new[]{stop});include.Keyboard(119,66,false,true,10);var included=include.Finish(20);Assert(included.Count==2&&included[0].Kind==ActionKind.KeyDown&&included[1].Kind==ActionKind.KeyUp&&included[1].Interval==10,"Included stop chord not balanced");
  var combo=new RecordedInputBuffer(0,false,new[]{Shortcut.Parse("Ctrl+Alt+R")});combo.Keyboard(17,29,false,true,10);combo.Keyboard(18,56,false,true,20);combo.Keyboard(82,19,false,true,30);Assert(combo.Finish(40).Count==0,"Hotkey modifiers leaked");
  var used=new RecordedInputBuffer(0,false,new[]{Shortcut.Parse("Ctrl+R")});used.Keyboard(17,29,false,true,10);used.Keyboard(67,46,false,true,20);used.Keyboard(67,46,false,false,30);used.Keyboard(82,19,false,true,40);var kept=used.Finish(50);Assert(kept.Select(s=>s.KeyCode).SequenceEqual(new[]{17,67,67,17})&&kept[^1].Kind==ActionKind.KeyUp,"Filtering destroyed prior legitimate Ctrl+C or left Ctrl held");
  var reuse=new RecordedInputBuffer(0,false,new[]{Shortcut.Parse("Ctrl+F9")});reuse.Keyboard(17,29,false,true,10);reuse.Keyboard(120,67,false,true,20);reuse.Keyboard(120,67,false,false,30);reuse.Keyboard(67,46,false,true,40);reuse.Keyboard(67,46,false,false,50);reuse.Keyboard(17,29,false,false,60);var resumed=reuse.Finish(60);Assert(resumed.Select(s=>s.KeyCode).SequenceEqual(new[]{17,67,67,17})&&resumed[0].Interval==40,"Suppressed modifier was not restored for subsequent ordinary keys");
  var mixed=new RecordedInputBuffer(100,false,new[]{stop});mixed.Mouse(new(){Kind=ActionKind.Move,X=10,Duration=0},110);mixed.Keyboard(65,30,false,true,115);mixed.Keyboard(65,30,false,false,120);mixed.Mouse(new(){Kind=ActionKind.Down,X=20,Duration=0},130);var timeline=mixed.Finish(140);Assert(timeline.Select(s=>s.Interval).SequenceEqual(new[]{10,5,5,10}),"Mouse and keyboard clocks diverged");
  var chord=new HotkeyBinding(3,"停止",stop);using var gate=new HotkeyOriginGate(()=>new[]{chord},false);gate.Observe(119,true,true);Assert(gate.ConsumeInjected(3),"Replayed self hotkey not recognized");gate.Observe(119,false,true);gate.Observe(119,true,true);gate.Observe(119,true,false);Assert(!gate.ConsumeInjected(3),"Physical emergency stop was suppressed");
  int emergency=0;using(var fallback=new HotkeyOriginGate(()=>new[]{chord},false,()=>emergency++)){fallback.Observe(17,true,false);fallback.Observe(17,true,true);fallback.Observe(17,false,true);fallback.Observe(119,true,false);Assert(emergency==1,"Held replay modifier blocked physical emergency stop");}
  var modifiedStop=new RecordedInputBuffer(0,false,new[]{stop},emergencyStop:stop);modifiedStop.Keyboard(17,29,false,true,10);modifiedStop.Keyboard(119,66,false,true,20);Assert(modifiedStop.Finish(30).Count==0,"Emergency chord with extra modifier leaked into recording");
  var input=typeof(Engine).Assembly.GetType("InputFlowStudio.Native+Input")!;Assert(System.Runtime.InteropServices.Marshal.SizeOf(input)==(IntPtr.Size==8?40:28),"SendInput ABI mismatch");
  var settings=new AppSettings{RecordKeyboard=false,IncludeControlHotkeys=true};var copy=settings.Copy();Assert(!copy.RecordKeyboard&&copy.IncludeControlHotkeys,"Keyboard recording settings not persisted");
  var recorder=new MouseRecorder{RecordKeyboard=true};try{recorder.Start(_=>{},IntPtr.Zero);}finally{recorder.Stop();}using(var installedGate=new HotkeyOriginGate(()=>Array.Empty<HotkeyBinding>())){}
  Console.WriteLine("Real keyboard/mouse hook installation and cleanup: PASS");
  Console.WriteLine("Keyboard capture, stop/chord inclusion toggle, modifier reuse, mixed timestamps, self-hotkey guard, physical stop priority and INPUT ABI: PASS");
 }
