sealed class FakeRecorder : IMouseRecorder {Action<Step>? captured;public int Starts;public void Start(Action<Step> action,IntPtr excluded){captured=action;Starts++;}public void Stop(){captured=null;}public void Emit(Step s)=>captured?.Invoke(s);}
sealed class FakeMouse : IMouseOutput {public int Cost;public bool Fail;public volatile bool Held;public int Moves;public int Releases;ScreenPoint point;public ScreenPoint Position()=>point;public void Move(int x,int y){if(Fail)throw new InvalidOperationException("Injected output failure");if(Cost>0)Thread.Sleep(Cost);point=new(x,y);Interlocked.Increment(ref Moves);}public void Button(MouseButton b,bool down){Held=down;}public void Wheel(int delta){}public void ReleaseAll(){Held=false;Interlocked.Increment(ref Releases);}}

sealed class FakeRegistry : IHotkeyRegistry {public Dictionary<int,Shortcut> Registered=new();public Shortcut? Blocked;public bool Register(int id,Shortcut value){if(value==Blocked)return false;Registered[id]=value;return true;}public void Unregister(int id)=>Registered.Remove(id);}

sealed class FakeDialogs : IPlanDialogs {
 public RecordingDecision Decision=new(RecordingDestination.Overwrite);public bool DeleteConfirmed=true;public int DeletePrompts,RecordingPrompts;public string? RenameTo {get;set;}
 public RecordingDecision ChooseRecording(Plan current,string suggested,Func<string,RecordingDestination,string?> error){RecordingPrompts++;return Decision;}
 public bool ConfirmDelete(string title,string message){DeletePrompts++;return DeleteConfirmed;}
 public UnsavedDecision SaveDecision {get;set;}=UnsavedDecision.Save; public int SavePrompts;
 public UnsavedDecision ResolveUnsaved(string action,int count,bool allowDiscard){SavePrompts++;return SaveDecision;}
 public string? Rename(string current,Func<string,string?> error)=>RenameTo;
}

sealed class FailingStore : IPlanStore {public bool Fail;readonly MemoryPlanStore memory=new();public System.Collections.ObjectModel.ObservableCollection<Plan> Load()=>memory.Load();public void Save(IEnumerable<Plan> plans){if(Fail)throw new System.IO.IOException("Injected disk failure");memory.Save(plans);}}


sealed class FakeKeyboard : IKeyboardOutput {public System.Collections.Concurrent.ConcurrentQueue<(int Key,int Scan,bool Extended,bool Down)> Events=new();public System.Collections.Concurrent.ConcurrentDictionary<int,bool> Held=new();public int Releases;public void Key(int key,int scan,bool extended,bool down){Events.Enqueue((key,scan,extended,down));if(down)Held[key]=true;else Held.TryRemove(key,out _);}public void ReleaseAll(){Held.Clear();Interlocked.Increment(ref Releases);}}
